// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.26;

contract Tipi {
    // enum della slide 14: fuori dal contratto diventa uint8
    enum ActionChoices { GoLeft, GoRight, GoStraight, SitStill }
    ActionChoices public choice;

    // constant: sostituita a compile time; immutable: fissata nel costruttore
    uint public constant MAX = 100;
    address public immutable creator;
    // un letterale esadecimale con checksum valido è di tipo address
    address public constant ESEMPIO = 0xdCad3a6d3569DF655070DEd06cb7A1b2Ccd1D3AF;

    constructor() { creator = msg.sender; }

    function setGoStraight() public { choice = ActionChoices.GoStraight; }

    // divisione intera: tronca verso zero
    function divisioni() public pure returns (uint, int, int, int) {
        uint a = 7;
        int b = 7;
        int c = -7;
        return (a / 2, b / 2, c / 2, c % 2);
    }

    // dalla 0.8 l'overflow fa revert (Panic 0x11)...
    function overflow(uint8 x) public pure returns (uint8) { return x + 1; }
    // ...a meno di chiederlo esplicitamente
    function overflowUnchecked(uint8 x) public pure returns (uint8) {
        unchecked { return x + 1; }
    }

    // valori di default e dimensioni
    function defaults() public pure returns (bool, uint, int8, bytes32, address, uint, int8) {
        bool b; uint u; int8 i; bytes32 h; address a;
        return (b, u, i, h, a, type(uint8).max, type(int8).min);
    }

    // unità (slide 23)
    function unita() public pure returns (uint, uint, uint, uint) {
        return (1 gwei, 1 ether, 1 days, 1 weeks);
    }
}

