import { network } from "hardhat";
import { getContractAddress } from "viem";

const { viem } = await network.create();
const pc = await viem.getPublicClient();
const [alice, bob] = await viem.getWalletClients();

const creator = await viem.deployContract("Creator");
console.log("Creator:", creator.address);

// Prima di createCreated, innerContarct = address(0): la chiamata fallisce
try { await creator.read.getInnerContractX(); }
catch (e: any) { console.log("getInnerContractX() prima della creazione:", e.details); }

// Un contratto crea un altro contratto (CREATE dal contratto, non da un EOA)
const nonceC = await pc.getTransactionCount({ address: creator.address });
const previsto = getContractAddress({ from: creator.address, nonce: BigInt(nonceC) });
const r = await pc.waitForTransactionReceipt({ hash: await creator.write.createCreated([5n]) });
console.log(`createCreated(5): gasUsed ${r.gasUsed}; Created previsto a ${previsto}`);
console.log("getInnerContractX() =", await creator.read.getInnerContractX());
await creator.write.incrementInnerContractX();
console.log("dopo incrementInnerContractX: x =", await creator.read.getInnerContractX());

// Lo stesso Created visto direttamente dall'esterno (address -> tipo contratto)
const created = await viem.getContractAt("Created", previsto);
console.log("Created.get() letto direttamente =", await created.read.get());

// overrideCreated: chiunque (qui bob) punta Creator a un altro Created
const altro = await viem.deployContract("Created", [999n], { client: { wallet: bob } });
const creatorBob = await viem.getContractAt("Creator", creator.address, { client: { wallet: bob } });
await creatorBob.write.overrideCreated([altro.address]);
console.log("dopo overrideCreated da bob: getInnerContractX() =", await creator.read.getInnerContractX());

