contract Logic {
    uint public x;          // slot 0
    address public who;     // slot 1
    function set(uint v) external { x = v; who = msg.sender; }
}

contract Proxy {
    uint public x;          // stesso layout di Logic
    address public who;
    function viaDelegate(address logic, uint v) external {
        (bool ok, ) = logic.delegatecall(abi.encodeWithSignature("set(uint256)", v));
        require(ok, "delegatecall fallita");
    }
    function viaCall(address logic, uint v) external {
        (bool ok, ) = logic.call(abi.encodeWithSignature("set(uint256)", v));
        require(ok, "call fallita");
    }
    function viaStatic(address logic, uint v) external view returns (bool ok) {
        (ok, ) = logic.staticcall(abi.encodeWithSignature("set(uint256)", v));
    }
}

