    function copie() public returns (uint inStorage, uint inMemoria) {
        uint[3] storage s = fisso;   // puntatore
        uint[3] memory m = fisso;    // copia
        s[0] = 100;                  // modifica lo stato
        m[1] = 200;                  // modifica solo la copia
        return (fisso[0], fisso[1]);
    }

    // calldata: sola lettura, niente copia
    function somma(uint[] calldata xs) external pure returns (uint t) {
        for (uint i = 0; i < xs.length; i++) t += xs[i];
    }
}

