// Un feed di prova che può fallire nei vari modi della slide 29
contract MockFeed is DataFeed {
    enum Mode { Ok, RequireMsg, Panic, BareRevert, CustomError, AssertFail }
    Mode public mode;
    error FeedRotto(uint codice);

    function setMode(Mode m) external { mode = m; }

    function getData(address) external view returns (uint) {
        if (mode == Mode.RequireMsg) require(false, "feed fermo");   // Error(string)
        if (mode == Mode.Panic) { uint zero = 0; return 1 / zero; }  // Panic(0x12)
        if (mode == Mode.BareRevert) revert();                       // nessun dato
        if (mode == Mode.CustomError) revert FeedRotto(42);          // errore personalizzato
        assert(mode != Mode.AssertFail);                             // Panic(0x01)
        return 1234;
    }
}

