// Slide 31: ordine dei modificatori, _ ripetuto, argomenti, errori personalizzati
contract Traccia is owned {
    string[] public log;
    bool public attivo = true;
    error NonAttivo();

    modifier a() { log.push("a prima"); _; log.push("a dopo"); }
    modifier b() { log.push("b prima"); _; log.push("b dopo"); }
    modifier dueVolte() { _; _; }
    modifier almeno(uint x, uint min) { require(x >= min, "troppo piccolo"); _; }
    modifier seAttivo() { if (!attivo) revert NonAttivo(); _; }

    function ordine() public a b { log.push("corpo"); }
    function ripeti() public dueVolte { log.push("corpo"); }
    function conArgomento(uint x) public almeno(x, 10) { log.push("corpo con x >= 10"); }

    // il pattern "disattiva invece di distruggere" della slide 34
    function disattiva() public onlyOwner { attivo = false; }
    function usa() public seAttivo { log.push("usato"); }

    function leggiLog() public view returns (string[] memory) { return log; }
    function pulisci() public { delete log; }
}

