// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.26;

contract Bomb {
    uint public x = 42;
    constructor() payable {}
    function boom(address payable to) external { selfdestruct(to); }
}

contract BombFactory {
    // crea e distrugge nella STESSA transazione: qui selfdestruct elimina davvero
    function createAndBoom(address payable to) external payable returns (address b) {
        Bomb x = new Bomb{value: msg.value}();
        x.boom(to);
        b = address(x);
    }
}

// Beneficiario che rifiuterebbe ETH normali: con selfdestruct li riceve lo stesso
contract NoReceive {}

