import { network } from "hardhat";

const { viem } = await network.create();
const pc = await viem.getPublicClient();
const [alice, bob] = await viem.getWalletClients();
const size = async (a: `0x${string}`) => ((await pc.getCode({ address: a })) ?? "0x").length / 2 - 1;

// Caso 1: deploy in una tx, selfdestruct in una tx successiva (dopo Cancun)
const bomb = await viem.deployContract("Bomb", [], { value: 500n });
const prima = await pc.getBalance({ address: bob.account.address });
await bomb.write.boom([bob.account.address]);
console.log("caso 1: bob riceve", (await pc.getBalance({ address: bob.account.address })) - prima, "wei",
  "| codice Bomb:", await size(bomb.address), "byte | x() =", await bomb.read.x());

// Caso 2: creazione e selfdestruct nella stessa transazione
const f = await viem.deployContract("BombFactory");
const { result: addr } = await f.simulate.createAndBoom([bob.account.address], { value: 300n });
await f.write.createAndBoom([bob.account.address], { value: 300n });
console.log("caso 2: codice del Bomb creato e distrutto:", await size(addr), "byte");

// Caso 3: il beneficiario non ha receive ma riceve comunque (la receive non viene eseguita)
const nr = await viem.deployContract("NoReceive");
try { await alice.sendTransaction({ to: nr.address, value: 1n }); }
catch (e: any) { console.log("caso 3: invio normale a NoReceive:", e.details); }
const bomb2 = await viem.deployContract("Bomb", [], { value: 77n });
await bomb2.write.boom([nr.address]);
console.log("caso 3: saldo NoReceive dopo selfdestruct:", await pc.getBalance({ address: nr.address }));
EOF
